Method.Implementation:
 #dim status as %Status	 
 set status = $$$OK
 $$$TRACE("Inside OnMessage method<" _ pRequest.StringValue _ ">")

 do ..JavaGateway.%Import(..JarFile) 	 

 try{
	 set ..objCdrTuxService = ##class(org.ihc.itf.cdr.CdrMmiEvents).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService)		
 }catch err{
	 $$$TRACE("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
     set status=$$$ERROR(" Exception while initializing Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)	    
 }

 set tableObj = ##class(IHC.ITF.Response.MmiEventsTable).%New()
 set tableObj.ListOfMmiEventsRows = ##class(%ListOfObjects).%New()
 set tableObj.DataExists = 0

 try {		 
	set output = ..objCdrTuxService.loadMmiEvents(..Events)
	$$$TRACE("Output after invocation of loadMmiEvent Java Method<" _ output _ ">")

	if ($LENGTH(output)>1){
		set tableObj.DataExists = 1
		set tableList = $LISTFROMSTRING(output, ..ROWBREAK) 
		$$$TRACE("Number of Rows from DSQL returned : " _$LISTLENGTH(tableList))		

		for iTarget=1:1:$LISTLENGTH(tableList) {
			set rowList = $LISTFROMSTRING(($LIST(tableList,iTarget)), ..COLUMBREAK)
			set rowObj = ##class(IHC.ITF.Response.MmiEventsRow).%New()
			set rowObj.UnitNumber = $LIST(rowList,1)
			set rowObj.AuditNumber = $LIST(rowList,2)
			set rowObj.TxTypeCid = $LIST(rowList,3)
			set rowObj.TxTime = $LIST(rowList,4)
			set rowObj.Employee = $LIST(rowList,5)
			set rowObj.Application = $LIST(rowList,6)
			set rowObj.ApplicationVersion = $LIST(rowList,7)
			set rowObj.MmiVersion = $LIST(rowList,8)
			set rowObj.FacilityCid = $LIST(rowList,9)
			if (($Length(rowObj.UnitNumber) > 0) && ($Length(rowObj.AuditNumber) > 0)){
				set retStat = ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.CdrCffDemogrToInitiateXmlSOAP.Lookup.SkipMap", rowObj.Application, .retVal )
				if (retVal = "Unknown") {
					$$$TRACE("Not skip: " _rowObj.AuditNumber)
					set retStat = ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.CdrCffDemogrToInitiateXmlSOAP.Lookup.DelMap", rowObj.Application, .retVal )
					//Check if UNIT_NUMBER present in mmi.mmi_site_audit table using unit_number, ROW_DELETE_AUDIT_NUM
					set rResponse = ..objCdrTuxService.checkMmiEvents(rowObj.UnitNumber,rowObj.AuditNumber)
					$$$TRACE("checkMmiEvents output is: "_rResponse)
					if ((retVal = "Unknown") && ('rResponse)) {
						//If TxTypeCid is '250' then do checkMergeMMI
						if (rowObj.TxTypeCid = "205") {
							//Get RESERVE_UNIT_NUMBER from mmi.mmi_merge_log using DROP_UNIT_NUMBER, MERGE_AUDIT_NUMBER
							set newMMI = ..objCdrTuxService.checkMergeMmi(rowObj.UnitNumber,rowObj.AuditNumber)
							$$$TRACE("Merge unit number is: "_newMMI)
							if ($LENGTH(newMMI) > 0){
								set rowObj.DelUnitNumber = rowObj.UnitNumber
								set rowObj.UnitNumber = newMMI
							}							
						}
						$$$TRACE("Send event: " _rowObj.AuditNumber)
						//insert the row into table
						do tableObj.ListOfMmiEventsRows.Insert(rowObj)																			
					}	
				} else {
					//filtered the application
					$$$TRACE("Application filtered: "_rowObj.Application)
				}
				//Unload relavant UnitNumber and AuditNumber row from mmi.mmi_itf_event_queue table
				set sResponse = ..objCdrTuxService.unloadMmiEvents(rowObj.UnitNumber,rowObj.AuditNumber)
			}			
		}
		//update dataExists variable
		$$$TRACE("Number of rows in MmiEventsTable " _ tableObj.ListOfMmiEventsRows.Count())
		if (tableObj.ListOfMmiEventsRows.Count() > 0) {
			set tableObj.DataExists = 1
		} else {
			set tableObj.DataExists = 0
		}
	}
	//set response of method to tableObject
	set pResponse = tableObj		
 } catch err {		 	
    $$$TRACE("Exception in calling CdrMmiEvents; AsSystemError is: " _err.AsSystemError() _ ";$ZERROR: " _ $ZERROR _ ";ErrName: " _ $ZCVT(err.Name,"O","HTML")_ "; ErrData: " _ err.Data _ "; ErrCode:" _ err.Code _ "ErrLocation:" _ err.Location)	    

    set status = $$$ERROR("Exception in calling CdrMmiEvents " _ err.Data)		    	     	 

    if errText["CONNECTIONERROR"{		   
	   set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError($CLASSNAME(),errText)
    }	    
    if errText["RESEND"{
	   set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError($CLASSNAME(),errText)
    }
    if errText["DATAERROR"{
	   set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError($CLASSNAME(),errText)
    }
    if errText["SHUTDOWN"{
	   set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError($CLASSNAME(),errText)
    }
 }

 try {		
	if $IsObject(..objCdrTuxService) {
		$$$TRACE("Disconnecting from CDR Tuxedo service...")
		do ..objCdrTuxService.shutdownTuxService()			
 		set ..objCdrTuxService = $$$NULLOREF
 	}
 } catch {
 	set tSC = $$$EnsSystemError
 }
 return status
